/**
 * The worker hub. A worker opens exactly one long-lived bidirectional stream and
 * keeps it open; all traffic in both directions is multiplexed over it. The
 * worker always dials out — the control plane never initiates a connection.
 */
export type WorkerHubService = typeof WorkerHubService;
export const WorkerHubService = {
  session: {
    path: "/rsagent.v1.WorkerHub/Session" as const,
    requestStream: true as const,
    responseStream: true as const,
    requestSerialize: (value: WorkerMessage): Buffer => Buffer.from(WorkerMessage.encode(value).finish()),
    requestDeserialize: (value: Buffer): WorkerMessage => WorkerMessage.decode(value),
    responseSerialize: (value: ServerMessage): Buffer => Buffer.from(ServerMessage.encode(value).finish()),
    responseDeserialize: (value: Buffer): ServerMessage => ServerMessage.decode(value),
  },
} as const;

